#define MAX_WORDS 100000

typedef struct {
  char *words[MAX_WORDS];
  int counts[MAX_WORDS];
  int size;
} WordsFrequency;

WordsFrequency *wordsFrequencyCreate(char **book, int bookSize) {
  WordsFrequency *obj = (WordsFrequency *)malloc(sizeof(WordsFrequency));
  obj->size = 0;
  for (int i = 0; i < bookSize; i++) {
    int found = -1;
    for (int j = 0; j < obj->size; j++) {
      if (strcmp(obj->words[j], book[i]) == 0) {
        found = j;
        break;
      }
    }
    if (found >= 0) {
      obj->counts[found]++;
    } else {
      obj->words[obj->size] = book[i];
      obj->counts[obj->size] = 1;
      obj->size++;
    }
  }
  return obj;
}

int wordsFrequencyGet(WordsFrequency *obj, char *word) {
  for (int j = 0; j < obj->size; j++) {
    if (strcmp(obj->words[j], word) == 0) return obj->counts[j];
  }
  return 0;
}

class WordsFrequency {
  unordered_map<string, int> freq;

public:
  WordsFrequency(vector<string> &book) {
    for (const string &w : book) freq[w]++;
  }
  int get(string word) { return freq.count(word) ? freq[word] : 0; }
};

type WordsFrequency struct {
	freq map[string]int
}

func Constructor(book []string) WordsFrequency {
	freq := map[string]int{}
	for _, w := range book {
		freq[w]++
	}
	return WordsFrequency{freq: freq}
}

func (w *WordsFrequency) Get(word string) int {
	return w.freq[word]
}

class WordsFrequency {
  private Map<String, Integer> freq = new HashMap<>();

  public WordsFrequency(String[] book) {
    for (String w : book) freq.put(w, freq.getOrDefault(w, 0) + 1);
  }

  public int get(String word) {
    return freq.getOrDefault(word, 0);
  }
}

class WordsFrequency:
    def __init__(self, book: List[str]):
        self.freq = Counter(book)

    def get(self, word: str) -> int:
        return self.freq.get(word, 0)

impl WordsFrequency {
  pub fn new(book: Vec<String>) -> Self {
    let mut freq = HashMap::new();
    for w in book {
      *freq.entry(w).or_insert(0) += 1;
    }
    WordsFrequency { freq }
  }

  pub fn get(&self, word: String) -> i32 {
    *self.freq.get(&word).unwrap_or(&0)
  }
}

class WordsFrequency {
  private freq = new Map<string, number>();

  constructor(book: string[]) {
    for (const w of book) this.freq.set(w, (this.freq.get(w) ?? 0) + 1);
  }

  get(word: string): number {
    return this.freq.get(word) ?? 0;
  }
}
